CREATE TABLE `craft` (
  `id` int(10) NOT NULL,
  `note` varchar(255) DEFAULT '',
  `craft_nameid` int(10) NOT NULL DEFAULT '0',
  `craft_itemid` varchar(255) NOT NULL DEFAULT '',
  `craft_count` varchar(255) NOT NULL DEFAULT '',
  `craft_enchant` varchar(255) NOT NULL DEFAULT '',
  `material` varchar(255) NOT NULL DEFAULT '',
  `material_count` varchar(255) NOT NULL DEFAULT '',
  `material_enchant` varchar(255) NOT NULL DEFAULT '',
  `material_bless` varchar(255) NOT NULL DEFAULT '',
  `min_level` int(10) NOT NULL DEFAULT '1',
  `max_level` int(10) NOT NULL DEFAULT '99',
  `min_lawful` int(10) NOT NULL DEFAULT '-32768',
  `max_lawful` int(10) NOT NULL DEFAULT '32767',
  `min_karma` int(10) NOT NULL DEFAULT '-2147483648',
  `max_karma` int(10) NOT NULL DEFAULT '2147483647',
  `max_count` int(10) NOT NULL DEFAULT '100',
  `change` int(10) NOT NULL DEFAULT '100',
  `add_chance_itemid` int(10) NOT NULL DEFAULT '0',
  `fail_itemid` int(10) NOT NULL DEFAULT '0' COMMENT '失敗時退回的道具',
  `fail_item_count` int(10) NOT NULL DEFAULT '0' COMMENT '失敗時退回的道具數量',
  `perfect_chance` int(1) NOT NULL DEFAULT '0' COMMENT '大成功機率',
  PRIMARY KEY (`id`,`material_enchant`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

